+        }
+
+        $segments[] = $segment;
+    }
+
+    $normalized = ($isAbsolute ? '/' : '').implode('/', $segments);
+
+    if ($normalized !== '') {
+        return $normalized;
+    }
+
+    return $isAbsolute ? '/' : '.';
+}
